1	package versioncheck
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"os"
11		"path/filepath"
12		"runtime"
13		"strings"
14		"time"
15	
16		"github.com/entireio/cli/cmd/entire/cli/logging"
17		"github.com/entireio/cli/cmd/entire/cli/versioninfo"
18		"github.com/entireio/cli/internal/entireclient/userdirs"
19		"golang.org/x/mod/module"
20		"golang.org/x/mod/semver"
21	)
22	
23	const goosWindows = "windows"
24	
25	// goos is a test seam for runtime.GOOS so the Windows-specific auto-install
26	// gating can be exercised from a non-Windows host.
27	var goos = runtime.GOOS
28	
29	const (
30		installManagerBrew    = "brew"
31		installManagerMise    = "mise"
32		installManagerScoop   = "scoop"
33		installManagerUnknown = "unknown"
34		installChannelStable  = "stable"
35		installChannelNightly = "nightly"
36	)
37	
38	// CheckAndNotify performs a version check and notifies the user if a newer version is available.
39	// This is the main entry point for the version check system.
40	// The function is silent on all errors to avoid interrupting CLI operations.
41	func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
42		// Skip checks for local/unreleased builds.
43		if isDevBuild(currentVersion) {
44			return
45		}
46	
47		// Ensure the global config directory exists
48		if err := ensureGlobalConfigDir(); err != nil {
49			// Silent failure - don't block CLI operations
50			return
51		}
52	
53		// Load the cache to check when we last fetched
54		cache, err := loadCache()
55		if err != nil {
56			cache = &VersionCache{}
57		}
58	
59		// Skip if we checked recently (within 24 hours)
60		if time.Since(cache.LastCheckTime) < checkInterval {
61			return
62		}
63	
64		// Fetch the latest version from the appropriate channel
65		var latestVersion string
66		if isNightly(currentVersion) {
67			latestVersion, err = fetchLatestNightlyVersion(ctx)
68		} else {
69			latestVersion, err = fetchLatestVersion(ctx)
70		}
71	
72		// Always update cache to avoid retrying on every CLI invocation
73		cache.LastCheckTime = time.Now()
74		if saveErr := saveCache(cache); saveErr != nil {
75			logging.Debug(ctx, "version check: failed to save cache",
76				"error", saveErr.Error())
77		}
78	
79		if err != nil {
80			logging.Debug(ctx, "version check: failed to fetch latest version",
81				"error", err.Error())
82			return
83		}
84	
85		// Show notification and offer an interactive upgrade when outdated
86		if isOutdated(currentVersion, latestVersion) {
87			if cache.SkippedVersion == versionCacheKey(latestVersion) {
88				return
89			}
90	
91			action := MaybeAutoUpdate(ctx, w, currentVersion, latestVersion)
92			if action == autoUpdateActionSkipUntilNextVersion {
93				cache.SkippedVersion = versionCacheKey(latestVersion)
94				if saveErr := saveCache(cache); saveErr != nil {
95					logging.Debug(ctx, "version check: failed to save skipped version",
96						"error", saveErr.Error())
97				}
98			}
99		}
100	}
101	
102	// globalConfigDirPath returns the CLI's global config directory. Resolution
103	// lives in userdirs.Config — the single implementation shared by all
104	// config-dir consumers (contexts.json, the file token store, this cache).
105	func globalConfigDirPath() string {
106		return userdirs.Config()
107	}
108	
109	// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
110	func ensureGlobalConfigDir() error {
111		//nolint:gosec // ~/.config/entire is user home directory, 0o755 is appropriate
112		if err := os.MkdirAll(globalConfigDirPath(), 0o755); err != nil {
113			return fmt.Errorf("creating config directory: %w", err)
114		}
115	
116		return nil
117	}
118	
119	// cacheFilePath returns the full path to the version check cache file.
120	func cacheFilePath() string {
121		return filepath.Join(globalConfigDirPath(), cacheFileName)
122	}
123	
124	// loadCache loads the version check cache from disk.
125	// Returns an error if the file doesn't exist or is corrupted.
126	func loadCache() (*VersionCache, error) {
127		data, err := os.ReadFile(cacheFilePath())
128		if err != nil {
129			return nil, fmt.Errorf("reading cache file: %w", err)
130		}
131	
132		var cache VersionCache
133		if err := json.Unmarshal(data, &cache); err != nil {
134			return nil, fmt.Errorf("parsing cache: %w", err)
135		}
136	
137		return &cache, nil
138	}
139	
140	// saveCache saves the version check cache to disk.
141	// Uses atomic write semantics (write to temp file, then rename).
142	func saveCache(cache *VersionCache) error {
143		filePath := cacheFilePath()
144	
145		// Marshal to JSON
146		data, err := json.MarshalIndent(cache, "", "  ")
147		if err != nil {
148			return fmt.Errorf("marshaling cache: %w", err)
149		}
150	
151		// Write to temp file first (atomic write)
152		dir := filepath.Dir(filePath)
153		tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
154		if err != nil {
155			return fmt.Errorf("creating temp file: %w", err)
156		}
157		defer os.Remove(tmpFile.Name())
158	
159		if _, err := tmpFile.Write(data); err != nil {
160			_ = tmpFile.Close() // cleanup on error path
161			return fmt.Errorf("writing cache: %w", err)
162		}
163	
164		if err := tmpFile.Close(); err != nil {
165			return fmt.Errorf("closing temp file: %w", err)
166		}
167	
168		// Rename temp file to final location
169	
170		if err := os.Rename(tmpFile.Name(), filePath); err != nil {
171			return fmt.Errorf("renaming cache file: %w", err)
172		}
173	
174		return nil
175	}
176	
177	// fetchLatestVersion fetches the latest stable version tag from the GitHub API.
178	func fetchLatestVersion(ctx context.Context) (string, error) {
179		ctx, cancel := context.WithTimeout(ctx, httpTimeout)
180		defer cancel()
181	
182		req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
183		if err != nil {
184			return "", fmt.Errorf("creating request: %w", err)
185		}
186	
187		req.Header.Set("Accept", "application/vnd.github+json")
188		req.Header.Set("User-Agent", versioninfo.UserAgent())
189	
190		client := &http.Client{}
191		resp, err := client.Do(req)
192		if err != nil {
193			return "", fmt.Errorf("fetching release info: %w", err)
194		}
195		defer resp.Body.Close()
196	
197		if resp.StatusCode != http.StatusOK {
198			return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
199		}
200	
201		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
202		if err != nil {
203			return "", fmt.Errorf("reading response: %w", err)
204		}
205	
206		version, err := parseGitHubRelease(body)
207		if err != nil {
208			return "", fmt.Errorf("parsing release: %w", err)
209		}
210		return version, nil
211	}
212	
213	// isNightly returns true if the version string is a nightly build.
214	func isNightly(version string) bool {
215		if !strings.HasPrefix(version, "v") {
216			version = "v" + version
217		}
218		return strings.Contains(semver.Prerelease(version), "nightly")
219	}
220	
221	// fetchLatestNightlyVersion fetches the latest nightly version tag from the GitHub releases list.
222	func fetchLatestNightlyVersion(ctx context.Context) (string, error) {
223		ctx, cancel := context.WithTimeout(ctx, httpTimeout)
224		defer cancel()
225	
226		req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubReleasesURL+"?per_page=20", nil)
227		if err != nil {
228			return "", fmt.Errorf("creating request: %w", err)
229		}
230	
231		req.Header.Set("Accept", "application/vnd.github+json")
232		req.Header.Set("User-Agent", versioninfo.UserAgent())
233	
234		client := &http.Client{}
235		resp, err := client.Do(req)
236		if err != nil {
237			return "", fmt.Errorf("fetching releases: %w", err)
238		}
239		defer resp.Body.Close()
240	
241		if resp.StatusCode != http.StatusOK {
242			return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
243		}
244	
245		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
246		if err != nil {
247			return "", fmt.Errorf("reading response: %w", err)
248		}
249	
250		var releases []GitHubRelease
251		if err := json.Unmarshal(body, &releases); err != nil {
252			return "", fmt.Errorf("parsing JSON: %w", err)
253		}
254	
255		for _, r := range releases {
256			if r.Prerelease && strings.Contains(r.TagName, "-nightly.") {
257				return r.TagName, nil
258			}
259		}
260	
261		return "", errors.New("no nightly release found")
262	}
263	
264	// parseGitHubRelease parses the GitHub API response and returns the latest stable version tag.
265	// Filters out prerelease versions.
266	func parseGitHubRelease(body []byte) (string, error) {
267		var release GitHubRelease
268		if err := json.Unmarshal(body, &release); err != nil {
269			return "", fmt.Errorf("parsing JSON: %w", err)
270		}
271	
272		if release.Prerelease {
273			return "", errors.New("only prerelease versions available")
274		}
275	
276		if release.TagName == "" {
277			return "", errors.New("empty tag name")
278		}
279	
280		return release.TagName, nil
281	}
282	
283	// isOutdated compares current and latest versions using semantic versioning.
284	// Returns true if current < latest.
285	func isOutdated(current, latest string) bool {
286		// Ensure versions have "v" prefix for semver package
287		if !strings.HasPrefix(current, "v") {
288			current = "v" + current
289		}
290		if !strings.HasPrefix(latest, "v") {
291			latest = "v" + latest
292		}
293	
294		// Local/unreleased builds shouldn't trigger update notifications.
295		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
296		if isDevBuild(current) {
297			return false
298		}
299	
300		// semver.Compare returns -1 if current < latest
301		return semver.Compare(current, latest) < 0
302	}
303	
304	// isDevBuild reports whether v identifies a local, unreleased build that
305	// should not be nagged to update. This covers the "dev" sentinel and empty
306	// string (an unstamped binary), a Go pseudo-version (built from a commit that
307	// isn't a tagged release), and any build carrying +metadata such as "+dirty".
308	// Released builds — stable tags, nightly tags, and `go install ...@<tag>` —
309	// have clean semver and return false.
310	func isDevBuild(v string) bool {
311		if v == "" || v == "dev" {
312			return true
313		}
314		if !strings.HasPrefix(v, "v") {
315			v = "v" + v
316		}
