func TestResolvePlugin_BuiltinWins(t *testing.T) { //nolint:paralleltest // mutates PATH via t.Setenv
	dir := t.TempDir()
	writePluginBinary(t, dir, "entire-session", filepath.Join(dir, "args.txt"), 0)
